import os
import redis
from flask_limiter import Limiter
from flask_sqlalchemy import SQLAlchemy
from flask_limiter.util import get_remote_address
from flask_login import LoginManager, current_user
from openai import OpenAI

from app.config import _REDIS_URL


db = SQLAlchemy()
login_manager = LoginManager()
login_manager.login_view = "auth.login"
redis_client = redis.from_url(_REDIS_URL, decode_responses=True) if _REDIS_URL else None
_LIMITER_STORAGE = _REDIS_URL or "memory://"
limiter = Limiter(
    key_func=get_remote_address,
    storage_uri=_LIMITER_STORAGE,
    storage_options={"socket_connect_timeout": 2} if _REDIS_URL else {},
    in_memory_fallback_enabled=True,
)
openai_client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"), timeout=30.0, max_retries=2)

def _user_or_ip_key():
    """Rate-limit key: the user id when logged in, else the client IP. The AI
    routes are all @login_required, so in practice each account gets its own
    budget regardless of source IP."""
    try:
        if current_user.is_authenticated:
            return f"user:{current_user.id}"
    except Exception:
        pass
    return get_remote_address()
